    const sumOf = (rows: Row[], key = 'amount') => rows.reduce((n: number, x: Row) => n + (x[key] || 0), 0), moveSum = (kind: string) => sumOf(cashMoves.filter((m: Row) => m.kind === kind));
    const expectedCash = (openedCash?.initial || 0) + sumOf(cashPays.filter((p: Row) => p.method === 'cash')) + sumOf(cashPays.filter((p: Row) => p.method === 'cash'), 'tip') + moveSum('income') - moveSum('expense') - moveSum('withdrawal');
    const mexicoNow = (() => { const d = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Mexico_City' })); return d.getHours() + d.getMinutes() / 60; })();
